def f():
    from BigDFT.Atoms import Atom
    carbon = Atom(C=[0.0, 0.0, 0.0], units='bohr')
    return (carbon.atomic_number, carbon.atomic_weight)

def f():
    from BigDFT.Atoms import Atom
    from BigDFT.Fragments import Fragment
    atoms = [
        Atom({'r': [0.0, 0.0, 0.0], 'sym': 'C', 'units': 'bohr'}),
        Atom({'r': [1.0, 0.0, 0.0], 'sym': 'H', 'units': 'bohr'}),
        Atom({'r': [0.0, 1.0, 0.0], 'sym': 'H', 'units': 'bohr'})
    ]
    frag = Fragment(atomlist=atoms)
    return (len(frag), frag.nel)

def f():
    from BigDFT.Atoms import Atom
    from BigDFT.Fragments import Fragment
    from BigDFT.Systems import System

    frag1 = Fragment(atomlist=[
        Atom({'r': [0.0, 0.0, 0.0], 'sym': 'H', 'units': 'bohr'}),
        Atom({'r': [1.0, 0.0, 0.0], 'sym': 'H', 'units': 'bohr'})
    ])

    frag2 = Fragment(atomlist=[
        Atom({'r': [5.0, 0.0, 0.0], 'sym': 'C', 'units': 'bohr'})
    ])

    sys = System({'MOL1': frag1, 'MOL2': frag2})
    return len(sys)

def f():
    from BigDFT.Inputfiles import Inputfile

    input_dict = {
        'dft': {
            'hgrids': 0.4,
            'ixc': 'LDA'
        }
    }
    inp = Inputfile(input_dict)

    return (inp['dft']['hgrids'], inp['dft']['ixc'])
